// Generated by chart-to-tla.mjs from receipts.mmd. Reader states are the chart's own states.
export const regions = ["source","receipt"];
const LABELS = {
	"EquivalentCommit": "Equivalent commit",
	"Rollback": "Rollback",
	"MeaningfulCommit": "Meaningful commit",
	"Replay": "Replay"
};

// The actions the reader takes. facts.settled needs them. Add cause() and detail() as the spec grows.
export const readerActions = [];
export const state = (v) => regions.map((r) => v[r]).join(" | ");
export const step = (action) => LABELS[action] ?? action;
